// Total Non-Human Identities
let SPs = (AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ',')))) | where TimeGenerated >= ago(30d) | summarize by ServicePrincipalId | count | project Count;
let MIs = (AADManagedIdentitySignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ',')))) | where TimeGenerated >= ago(30d) | summarize by ServicePrincipalId | count | project Count;
union SPs, MIs
| summarize TotalIdentities = sum(Count)
| project Metric = 'Monitored Identities', Value = TotalIdentities, Status = '📊'

// Week-over-Week Failure Change
let ThisWeek = (AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ',')))) | where TimeGenerated >= ago(7d) | summarize TW = countif(ResultType != '0');
let LastWeek = (AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ',')))) | where TimeGenerated between (ago(14d) .. ago(7d)) | summarize LW = countif(ResultType != '0');
ThisWeek | extend p = 1 | join kind=leftouter (LastWeek | extend p = 1) on p
| extend LW = coalesce(LW, 1)
| extend Change = round((todouble(TW) - LW) / LW * 100, 0)
| extend Status = case(Change > 50, strcat('🔴 +', tostring(toint(Change)), '%'), Change > 10, strcat('🟠 +', tostring(toint(Change)), '%'), Change < -10, strcat('🟢 ', tostring(toint(Change)), '%'), '➡️ Stable')
| project Metric = 'WoW Failures', Value = TW, Status

// 30-Day Failure Rate Trend
let SPTrend = (AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
    | where TimeGenerated >= ago(30d)
    | summarize SPTotal = count(), SPFailed = countif(ResultType != '0') by bin(TimeGenerated, 1d)
    | extend FailureRate = iff(SPTotal == 0, 0.0, round(todouble(SPFailed) / SPTotal * 100, 1))
    | project TimeGenerated, FailureRate, Category = 'Service Principals';
let MITrend = (AADManagedIdentitySignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
    | where TimeGenerated >= ago(30d)
    | summarize MITotal = count(), MIFailed = countif(ResultType != '0') by bin(TimeGenerated, 1d)
    | extend FailureRate = iff(MITotal == 0, 0.0, round(todouble(MIFailed) / MITotal * 100, 1))
    | project TimeGenerated, FailureRate, Category = 'Managed Identities';
union SPTrend, MITrend
| render timechart

// Risk Distribution
let HighRisk = (AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
    | where TimeGenerated >= ago(7d)
    | summarize Total = count(), Failed = countif(ResultType != '0') by ServicePrincipalId
    | where Total > 0 and todouble(Failed) / Total > 0.5 and Failed > 20
    | count | project Category = '🔴 High Risk', Count;
let MediumRisk = (AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
    | where TimeGenerated >= ago(7d)
    | summarize Total = count(), Failed = countif(ResultType != '0') by ServicePrincipalId
    | where Total > 0 and todouble(Failed) / Total between (0.1 .. 0.5) and Failed > 5
    | count | project Category = '🟠 Medium Risk', Count;
let LowRisk = (AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
    | where TimeGenerated >= ago(7d)
    | summarize Total = count(), Failed = countif(ResultType != '0') by ServicePrincipalId
    | where Total > 0 and (todouble(Failed) / Total < 0.1 or Failed <= 5)
    | count | project Category = '🟢 Low Risk', Count;
union HighRisk, MediumRisk, LowRisk

// Managed Identity Baseline Trend Chart
let CurrentWeek = (AADManagedIdentitySignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated >= ago(7d)
| summarize CurrentSignIns = count() by bin(TimeGenerated, 1d)
| extend Period = "Current Week";
let PreviousWeek = (AADManagedIdentitySignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated between (ago(14d) .. ago(7d))
| summarize BaselineSignIns = count() by bin(TimeGenerated, 1d)
| extend AdjustedTime = datetime_add('day', 7, TimeGenerated)
| project TimeGenerated = AdjustedTime, BaselineSignIns, Period = "Baseline (Previous Week)";
CurrentWeek
| project TimeGenerated, SignIns = CurrentSignIns, Period
| union (PreviousWeek | project TimeGenerated, SignIns = BaselineSignIns, Period)
| render timechart

// Service Principal Baseline Trend Chart
let CurrentWeek = (AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated >= ago(7d)
| summarize CurrentSignIns = count() by bin(TimeGenerated, 1d)
| extend Period = "Current Week";
let PreviousWeek = (AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated between (ago(14d) .. ago(7d))
| summarize BaselineSignIns = count() by bin(TimeGenerated, 1d)
| extend AdjustedTime = datetime_add('day', 7, TimeGenerated)
| project TimeGenerated = AdjustedTime, BaselineSignIns, Period = "Baseline (Previous Week)";
CurrentWeek
| project TimeGenerated, SignIns = CurrentSignIns, Period
| union (PreviousWeek | project TimeGenerated, SignIns = BaselineSignIns, Period)
| render timechart

// Service Principal Activity Timeline
(AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated {TimeRange}
| extend Status = case(ResultType == "0", "Success", "Failed")
| summarize Count = count() by bin(TimeGenerated, 1h), Status
| render timechart

// Managed Identity Resource Distribution
(AADManagedIdentitySignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated {TimeRange}
| summarize Count = count() by Category
| order by Count desc

// Managed Identity Accessing Unusual Resources
let ResourceBaseline = (AADManagedIdentitySignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated between (ago(30d) .. ago(7d))
| where ResultType == "0"
| distinct ServicePrincipalId, ResourceDisplayName;
(AADManagedIdentitySignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated {TimeRange}
| where ResultType == "0"
| join kind=leftanti (ResourceBaseline) on ServicePrincipalId, ResourceDisplayName
| project TimeGenerated, ServicePrincipalName, ServicePrincipalId, ResourceDisplayName, Category
| order by TimeGenerated desc

// Managed Identity Activity Timeline
(AADManagedIdentitySignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated {TimeRange}
| extend Status = case(ResultType == "0", "Success", "Failed")
| summarize Count = count() by bin(TimeGenerated, 1h), Status
| render timechart

// Detect Illicit Consent Grant Attack Patterns
AuditLogs
| where TimeGenerated {TimeRange}
| where OperationName == "Consent to application"
| extend ConsentUser = tostring(InitiatedBy.user.userPrincipalName)
| extend ConsentIP = tostring(InitiatedBy.user.ipAddress)
| extend AppName = tostring(TargetResources[0].displayName)
| extend AppId = tostring(TargetResources[0].id)
| extend Permissions = tostring(TargetResources[0].modifiedProperties)
// Detect suspicious patterns
| extend IsSuspicious = case(
    // Consent from risky IP
    ConsentIP has_any ("tor", "vpn"), true,
    // High-risk permissions
    Permissions has_any ("Mail.Read", "Mail.Send", "Files.ReadWrite.All", "full_access"), true,
    // Unknown publisher apps
    AppName has_any ("test", "demo", "oauth", "token"), true,
    false
)
| where IsSuspicious == true
| project TimeGenerated, ConsentUser, ConsentIP, AppName, AppId, Permissions, IsSuspicious
| order by TimeGenerated desc

// CA Blocks Timeline for Service Principals
(AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated {TimeRange}
| where ConditionalAccessStatus == "failure" or ResultType in ("53000", "53001", "53002", "53003")
| summarize BlockedCount = count() by bin(TimeGenerated, 1h)
| render timechart

// User Geographic Distribution
let targetUser = '{SelectedForensicUser}';
(SigninLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated {ForensicTimeRange}
| where UserPrincipalName =~ targetUser or UserId == targetUser
| extend Country = tostring(LocationDetails.countryOrRegion)
| extend City = tostring(LocationDetails.city)
| summarize Count = count() by Country, City
| order by Count desc

// SP Activity Timeline
let targetSP = '{SelectedForensicSP}';
(AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated {ForensicTimeRange}
| where ServicePrincipalName =~ targetSP or ServicePrincipalId == targetSP
| summarize Success = countif(ResultType == '0'), Failed = countif(ResultType != '0') by bin(TimeGenerated, 1h)
| render timechart

// SP Resource Access
let targetSP = '{SelectedForensicSP}';
(AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated {ForensicTimeRange}
| where ServicePrincipalName =~ targetSP or ServicePrincipalId == targetSP
| summarize AccessCount = count() by ResourceDisplayName
| order by AccessCount desc

// MI Activity Timeline
let targetMI = '{SelectedForensicMI}';
(AADManagedIdentitySignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated {ForensicTimeRange}
| where ServicePrincipalName =~ targetMI or ServicePrincipalId == targetMI
| summarize Success = countif(ResultType == '0'), Failed = countif(ResultType != '0') by bin(TimeGenerated, 1h)
| render timechart

// MI Resource Access
let targetMI = '{SelectedForensicMI}';
(AADManagedIdentitySignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated {ForensicTimeRange}
| where ServicePrincipalName =~ targetMI or ServicePrincipalId == targetMI
| summarize AccessCount = count() by ResourceDisplayName
| order by AccessCount desc

// Device Activity Timeline
let targetDevice = '{SelectedForensicDevice}';
(SigninLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
| where TimeGenerated {ForensicTimeRange}
| where DeviceDetail.deviceId == targetDevice or DeviceDetail.displayName =~ targetDevice
| summarize Success = countif(ResultType == '0'), Failed = countif(ResultType != '0'), HighRisk = countif(RiskLevelDuringSignIn == 'high') by bin(TimeGenerated, 1h)
| render timechart

let allowlistCount = toscalar(_GetWatchlist('NetworkAllowlist') | count);
let totalSignins = toscalar((AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
    | where TimeGenerated > ago(24h)
    | count);
let afterExclusion = toscalar((AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs() | where isempty('{ExcludedIPs}') or not(ipv4_is_in_any_range(tostring(IPAddress), split(replace_string('{ExcludedIPs}', ' ', ''), ','))))
    | where TimeGenerated > ago(24h)
    | count);
print
    AllowlistEntries = allowlistCount,
    SigninsLast24h_Total     = totalSignins,
    SigninsLast24h_AfterAllow = afterExclusion,
    Suppressed               = totalSignins - afterExclusion
